import {types} from 'node:util';

export const ORIGINAL_WALLET_SERVICE_RUNTIME_PUBLICATION_NAMESPACE='wallet-product-session-v2-runtime-publication-metadata/v1';
export const ORIGINAL_WALLET_SERVICE_RUNTIME_PUBLICATION_MAX_BYTES=65536;
const BINDING=['keyId','roleDigest','instanceId','currentReference','gatewayManifestDigest','registryDigest'];
const OBSERVATION=['instanceId','currentReference','gatewayManifestDigest','registryDigest','observedAtMs','expiresAtMs','sequence','state'];
const RECORD=['binding','sequence','nonce','observationRaw','state','runtimeRaw'];
const fail=(code='WALLET_SERVICE_RUNTIME_METADATA_INVALID')=>{const error=new Error(code);error.code=code;throw error;};
function canonical(value){if(value===null||typeof value!=='object')return JSON.stringify(value);if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+canonical(value[key])).join(',')+'}';}
function capture(raw,limit=65536){const seen=new WeakSet();let nodes=0,budget=0;function visit(v,depth){if(++nodes>8192||depth>24)fail();if(v===null||typeof v==='boolean')return v;if(typeof v==='number'&&Number.isSafeInteger(v))return v;if(typeof v==='string'){budget+=Buffer.byteLength(v);if(budget>limit)fail('WALLET_SERVICE_RUNTIME_CAPACITY');return v;}if(!v||typeof v!=='object'||types.isProxy(v)||seen.has(v))fail();seen.add(v);const array=Array.isArray(v);if(array&&v.length>8192)fail();if(Object.getPrototypeOf(v)!==(array?Array.prototype:Object.prototype))fail();const descriptors=Object.getOwnPropertyDescriptors(v),out=array?[]:{};if(Reflect.ownKeys(descriptors).some(k=>typeof k!=='string'))fail();if(array&&Object.keys(descriptors).filter(k=>k!=='length').join(',')!==Array.from({length:v.length},(_,i)=>String(i)).join(','))fail();for(const [k,d]of Object.entries(descriptors)){if(array&&k==='length')continue;if(!d.enumerable||!Object.hasOwn(d,'value'))fail();budget+=Buffer.byteLength(k);if(budget>limit)fail('WALLET_SERVICE_RUNTIME_CAPACITY');Object.defineProperty(out,k,{value:visit(d.value,depth+1),enumerable:true,writable:true,configurable:true});}return out;}const value=visit(raw,0);if(Buffer.byteLength(canonical(value))>limit)fail('WALLET_SERVICE_RUNTIME_CAPACITY');return value;}
function exact(v,keys){if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).sort().join('|')!==[...keys].sort().join('|'))fail();}
function token(v){if(typeof v!=='string'||!/^[A-Za-z0-9._:-]{1,128}$/.test(v))fail();}
function hex(v){if(typeof v!=='string'||!/^[0-9a-f]{64}$/.test(v))fail();}
function bytes(v,size){if(typeof v!=='string'||!/^[A-Za-z0-9_-]+$/.test(v))fail();const b=Buffer.from(v,'base64url');if(b.length!==size||b.toString('base64url')!==v)fail();}
function time(v){if(!Number.isSafeInteger(v)||v<0)fail();}
function rawJSON(raw,limit){if(typeof raw!=='string'||Buffer.byteLength(raw)>limit)fail();let v;try{v=JSON.parse(raw);}catch{fail();}v=capture(v,limit);if(canonical(v)!==raw)fail();return v;}
function binding(v){exact(v,BINDING);token(v.keyId);token(v.instanceId);for(const k of ['roleDigest','currentReference','gatewayManifestDigest','registryDigest'])hex(v[k]);}
function observation(raw,b,sequence){const v=rawJSON(raw,8192);exact(v,OBSERVATION);for(const k of ['instanceId','currentReference','gatewayManifestDigest','registryDigest'])if(v[k]!==b[k])fail();if(v.sequence!==sequence||v.state!=='ready')fail();time(v.observedAtMs);time(v.expiresAtMs);if(v.expiresAtMs<=v.observedAtMs||v.expiresAtMs-v.observedAtMs>30000)fail();return v;}
function runtime(raw,record){const v=rawJSON(raw,8192);exact(v,['version','purpose','keyId','roleDigest','observation','signature']);if(v.version!==1||v.purpose!=='wallet-product-session-v2-runtime-observation/v1'||v.keyId!==record.binding.keyId||v.roleDigest!==record.binding.roleDigest||canonical(v.observation)!==record.observationRaw)fail();bytes(v.signature,64);}
function record(v){exact(v,RECORD);binding(v.binding);if(!Number.isSafeInteger(v.sequence)||v.sequence<1)fail();bytes(v.nonce,32);observation(v.observationRaw,v.binding,v.sequence);if(!['pending','UNKNOWN','signed'].includes(v.state))fail();if(v.state==='signed'){if(typeof v.runtimeRaw!=='string')fail();runtime(v.runtimeRaw,v);}else if(v.runtimeRaw!==null)fail();return v;}

export function emptyOriginalWalletServiceRuntimePublicationState(){return {version:1,purpose:ORIGINAL_WALLET_SERVICE_RUNTIME_PUBLICATION_NAMESPACE,sequenceHighWater:0,records:[]};}
export function parseOriginalWalletServiceRuntimePublicationState(raw){const state=capture(raw);exact(state,['version','purpose','sequenceHighWater','records']);if(state.version!==1||state.purpose!==ORIGINAL_WALLET_SERVICE_RUNTIME_PUBLICATION_NAMESPACE||!Array.isArray(state.records)||state.records.length>64||state.sequenceHighWater!==state.records.length)fail();const nonces=new Set();let unresolved=false;for(let i=0;i<state.records.length;i++){const r=record(state.records[i]);if(r.sequence!==i+1||nonces.has(r.nonce)||unresolved)fail();nonces.add(r.nonce);if(r.state!=='signed')unresolved=true;}return state;}
/** Pure next sequence/review material only, NOT a runtime readiness observer. */
export function prepareOriginalWalletServiceRuntimePublicationObservation(rawState,rawBinding,observedAtMs,expiresAtMs){const state=parseOriginalWalletServiceRuntimePublicationState(rawState),b=capture(rawBinding,8192);if(state.records.some(r=>r.state!=='signed'))fail('WALLET_SERVICE_RUNTIME_UNRESOLVED');if(state.records.length>=64)fail('WALLET_SERVICE_RUNTIME_CAPACITY');binding(b);time(observedAtMs);time(expiresAtMs);const v={instanceId:b.instanceId,currentReference:b.currentReference,gatewayManifestDigest:b.gatewayManifestDigest,registryDigest:b.registryDigest,observedAtMs,expiresAtMs,sequence:state.sequenceHighWater+1,state:'ready'};const observationRaw=canonical(v);observation(observationRaw,b,v.sequence);return {binding:b,sequence:v.sequence,observationRaw};}
/** SAME original catalog commit of this candidate must precede signing. */
export function reserveOriginalWalletServiceRuntimePublication(rawState,input){const state=parseOriginalWalletServiceRuntimePublicationState(rawState),v=capture(input,16384);exact(v,['binding','nonce','observationRaw']);binding(v.binding);bytes(v.nonce,32);const old=state.records.find(r=>r.nonce===v.nonce);if(old){if(canonical(old.binding)!==canonical(v.binding)||old.observationRaw!==v.observationRaw)fail('WALLET_SERVICE_RUNTIME_CONFLICT');return {state,record:capture(old),readOnly:true};}if(state.records.some(r=>r.state!=='signed'))fail('WALLET_SERVICE_RUNTIME_UNRESOLVED');const next=record({binding:v.binding,sequence:state.sequenceHighWater+1,nonce:v.nonce,observationRaw:v.observationRaw,state:'pending',runtimeRaw:null});state.sequenceHighWater=next.sequence;state.records.push(next);return {state:parseOriginalWalletServiceRuntimePublicationState(state),record:capture(next),readOnly:false};}
/** Persist UNKNOWN before entering the ONE genuine holder sign attempt. */
export function markOriginalWalletServiceRuntimePublicationUnknown(rawState,nonce){const state=parseOriginalWalletServiceRuntimePublicationState(rawState);bytes(nonce,32);const r=state.records.find(r=>r.nonce===nonce);if(!r)fail();const readOnly=r.state!=='pending';if(!readOnly)r.state='UNKNOWN';return {state,record:capture(r),readOnly};}
/** Structural receipt association only. A must verify the exact captured raw
 * with actual role/current/holder and same original Vault lease before commit. */
export function recordOriginalWalletServiceRuntimePublicationSigned(rawState,nonce,runtimeRaw){const state=parseOriginalWalletServiceRuntimePublicationState(rawState);bytes(nonce,32);const old=state.records.find(r=>r.nonce===nonce);if(!old)fail();const captured=canonical(rawJSON(runtimeRaw,8192));if(old.state==='signed'){if(old.runtimeRaw!==captured)fail('WALLET_SERVICE_RUNTIME_CONFLICT');return {state,record:capture(old),readOnly:true};}if(old.state!=='UNKNOWN')fail('WALLET_SERVICE_RUNTIME_UNKNOWN_REQUIRED');const next=record({...old,state:'signed',runtimeRaw:captured});Object.assign(old,next);return {state:parseOriginalWalletServiceRuntimePublicationState(state),record:capture(old),readOnly:false};}
/** Cold original record only: never renew, resend, replace nonce or sign. */
export function readOriginalWalletServiceRuntimePublication(rawState,nonce){const state=parseOriginalWalletServiceRuntimePublicationState(rawState);bytes(nonce,32);const r=state.records.find(r=>r.nonce===nonce);if(!r)fail();return {record:capture(r),readOnly:true};}
/** Mandatory at EVERY A same-catalog rewrite, not a permission assertion. */
export function assertOriginalWalletServiceRuntimePublicationRetention(previous,next){const old=parseOriginalWalletServiceRuntimePublicationState(previous),fresh=parseOriginalWalletServiceRuntimePublicationState(next);if(fresh.records.length<old.records.length||fresh.sequenceHighWater<old.sequenceHighWater)fail('WALLET_SERVICE_RUNTIME_RETENTION');for(let i=0;i<old.records.length;i++){const a=old.records[i],b=fresh.records[i],{state:as,runtimeRaw:ar,...ab}=a,{state:bs,runtimeRaw:br,...bb}=b;if(canonical(ab)!==canonical(bb))fail('WALLET_SERVICE_RUNTIME_RETENTION');if(as===bs){if(ar!==br)fail('WALLET_SERVICE_RUNTIME_RETENTION');}else if(!(as==='pending'&&bs==='UNKNOWN'&&br===null||as==='UNKNOWN'&&bs==='signed'))fail('WALLET_SERVICE_RUNTIME_RETENTION');}if(fresh.records.length>old.records.length){if(old.records.some(r=>r.state!=='signed'))fail('WALLET_SERVICE_RUNTIME_UNRESOLVED');for(const r of fresh.records.slice(old.records.length))if(r.state!=='pending'||r.runtimeRaw!==null)fail('WALLET_SERVICE_RUNTIME_RETENTION');}}
